import{useState}from'react';import{StyleSheet,Text}from'@/platform/react-native';import{useLocalSearchParams}from'@/router';import{useQuery}from'@tanstack/react-query';import{api}from'@/lib/api';import{Badge,Card,EmptyState,Header,Input,Muted,Screen,useAppTheme}from'@/components/UI';
export default function Decisions(){const{id}=useLocalSearchParams<{id:string}>();const{palette}=useAppTheme();const[q,setQ]=useState('');const r=useQuery<any[]>({queryKey:['decisions',id,q],queryFn:async()=>(await api.get(`/communities/${id}/decisions`,{params:{q}})).data});return <Screen scroll><Header title="Decision Register" subtitle="Search what the community decided and why"/><Input value={q} onChangeText={setQ} placeholder="Try: parking March, security, budget…"/>{!r.data?.length?<EmptyState title="No matching decisions" body="Final governance decisions will appear here with dates and actions."/>:r.data.map(d=><Card key={d.Id}><Text style={[s.title,{color:palette.text}]}>{d.Title}</Text><Muted>{new Date(d.DecisionDate).toLocaleDateString()}</Muted><Text style={[s.body,{color:palette.text}]}>{d.DecisionText}</Text><Badge text={`${d.ActionCount} action(s)`}/></Card>)}</Screen>};const s=StyleSheet.create({title:{fontSize:16,fontWeight:'900'},body:{marginVertical:8,lineHeight:21}})
